"""Row profiles, subset paths and monotone-state subset optimization."""
from nowcoder_editorials import CONTENT, add, read, reviewed_clone


def run():
    existing = read(CONTENT / 'reviewed.json')
    def put(n, *args, **kwargs):
        if f'nowcoder-global::{n}' not in existing:
            add(n, *args, **kwargs)
    put(16886, 1800, ['状态压缩', '动态规划'], '平原可放炮兵，同一行或列距离一、二格不能互相攻击，最大化数量。',
        '一行用mask表示布置，行内合法要求mask与左移1、左移2均不相交，且不占山地。纵向约束跨最近两行，因此状态保留上一行和上上行。枚举当前行mask，只需与前两行分别不相交，转移加当前炮数。更远的行互不影响。初始两行都为空，答案取末行所有状态最大。',
        r'''int n,m; cin >> n >> m; vector<int> blocked(n); for (int r = 0; r < n; r++) { string s; cin >> s; for (int c = 0; c < m; c++) if (s[c] == 'H') blocked[r] |= 1 << c; } vector<int> masks, count; for (int mask = 0; mask < (1 << m); mask++) if (!(mask & (mask << 1)) && !(mask & (mask << 2))) { masks.push_back(mask); count.push_back(__builtin_popcount((unsigned)mask)); } int states = masks.size(), neg = -1000000000; vector<vector<int>> dp(states,vector<int>(states,neg)); dp[0][0] = 0; for (int r = 0; r < n; r++) { vector<vector<int>> next(states,vector<int>(states,neg)); for (int current = 0; current < states; current++) if (!(masks[current] & blocked[r])) for (int previous = 0; previous < states; previous++) if (!(masks[current] & masks[previous])) for (int older = 0; older < states; older++) if (!(masks[current] & masks[older]) && dp[previous][older] != neg) next[current][previous] = max(next[current][previous],dp[previous][older] + count[current]); dp.swap(next); } int answer = 0; for (auto &row : dp) answer = max(answer,*max_element(row.begin(),row.end())); cout << answer;''',
        '山地不能挡住炮火。必须同时检查上上行，只有上一行状态不够。', complexity=r'合法行状态数 $S\le60$，时间 $O(NS^3+2^M)$，空间 $O(S^2+N)$。')
    put(20240, 1800, ['状态压缩', '计数动态规划'], '在n乘n棋盘放恰好k个互不攻击的国王，八方向近邻均攻击。',
        '预处理行内无相邻1的mask。两相邻行a、b相容，需a与b、b左移1、b右移1都不相交，分别排除竖直和两种斜攻击。dp[行mask][已放数]累加相容前行的方案，增加当前行1的数量。初始空前行、0个国王为1，处理n行后对放k个的所有末行求和。',
        r'''int n,k; cin >> n >> k; vector<int> mask, count; for (int x = 0; x < (1 << n); x++) if (!(x & (x << 1))) { mask.push_back(x); count.push_back(__builtin_popcount((unsigned)x)); } int states = mask.size(); vector<vector<int>> compatible(states); for (int a = 0; a < states; a++) for (int b = 0; b < states; b++) if (!(mask[a] & mask[b]) && !(mask[a] & (mask[b] << 1)) && !(mask[a] & (mask[b] >> 1))) compatible[a].push_back(b); vector<vector<long long>> dp(states,vector<long long>(k + 1)); dp[0][0] = 1; for (int r = 0; r < n; r++) { vector<vector<long long>> next(states,vector<long long>(k + 1)); for (int a = 0; a < states; a++) for (int b : compatible[a]) for (int used = 0; used + count[a] <= k; used++) next[a][used + count[a]] += dp[b][used]; dp.swap(next); } long long answer = 0; for (int x = 0; x < states; x++) answer += dp[x][k]; cout << answer;''',
        'k=0时空棋盘有一种方案。方案数使用64位，题目不要求取模。', complexity=r'行状态数 $S$，时间 $O(nkS^2+2^n)$，空间 $O(kS+S^2)$。')
    put(51189, 1800, ['状态压缩', '轮廓动态规划'], '用1乘2或2乘1骨牌铺满矩形，统计全部不同铺法，多组0 0结束。',
        '取较短边作列宽。行mask表示当前行哪些格已被上一行竖骨牌占住。对每个mask从左到右递归填剩余格：横放占当前行相邻两空格；竖放占当前格，并把下一行对应位设1。填完当前行后得到一个下一行mask转移。预处理全部行转移，再按行累加。初态与终态都必须为0，保证没有骨牌伸出上下边界。面积奇数时直接0。',
        r'''int rows, cols; while (cin >> rows >> cols && (rows || cols)) { if ((rows * cols) % 2) { cout << "0\n"; continue; } if (cols > rows) swap(rows,cols); int masks = 1 << cols; vector<vector<int>> transition(masks); for (int incoming = 0; incoming < masks; incoming++) { auto fill = [&](auto &&self, int c, int outgoing) -> void { if (c == cols) { transition[incoming].push_back(outgoing); return; } if (incoming >> c & 1) self(self,c + 1,outgoing); else { self(self,c + 1,outgoing | (1 << c)); if (c + 1 < cols && !(incoming >> (c + 1) & 1)) self(self,c + 2,outgoing); } }; fill(fill,0,0); } vector<long long> dp(masks), next(masks); dp[0] = 1; for (int r = 0; r < rows; r++) { fill(next.begin(),next.end(),0); for (int mask = 0; mask < masks; mask++) for (int out : transition[mask]) next[out] += dp[mask]; dp.swap(next); } cout << dp[0] << '\n'; }''',
        '对称、旋转后不同的铺法依然分别计数。最后不是所有mask求和，只能取没有悬空竖骨牌的0。', complexity=r'短边 $W\le11$，行转移总数 $E$，时间 $O(2^W3^W+HE)$ 为保守界，空间 $O(2^W+E)$。')
    put(15832, 1500, ['状态压缩', '动态规划'], '两原子碰撞指定一方消失，最大化直到只剩一个原子的总能量。',
        '状态mask记录还存在的原子，dp[mask]为到达该集合的最大已获能量。初始全部存在为0。枚举仍存在的两个不同原子i、j，让i消灭j，获得power[i][j]，清掉j位。每次集合缩小，按mask递减处理即可保证前驱已求。最后在所有单元素集合中取最大。全为正值，合并到只剩一个一定最优。',
        r'''int n; while (cin >> n && n) { vector<vector<int>> power(n,vector<int>(n)); for (auto &row : power) for (int &x : row) cin >> x; vector<int> dp(1 << n,-1000000000); dp.back() = 0; for (int mask = (1 << n) - 1; mask > 0; mask--) if (dp[mask] >= 0) for (int i = 0; i < n; i++) if (mask >> i & 1) for (int j = 0; j < n; j++) if (i != j && (mask >> j & 1)) dp[mask ^ (1 << j)] = max(dp[mask ^ (1 << j)],dp[mask] + power[i][j]); int answer = 0; for (int i = 0; i < n; i++) answer = max(answer,dp[1 << i]); cout << answer << '\n'; }''',
        '矩阵第i行第j列表示j消失、i保留，不能反用。原子身份在后续碰撞中不变，无需额外记录能量。', complexity=r'每组时间 $O(n^2 2^n)$，空间 $O(2^n+n^2)$。')
    put(25088, 1600, ['状态压缩', '动态规划'], '只能在肥沃格种玉米，上下左右不能相邻，统计方案模一亿，空方案也算。',
        '一行用mask表示，合法mask不能有相邻1，还必须是本行肥沃位集的子集。上下行a、b只需a&b=0，因为斜对角不相邻。dp[当前mask]累加所有相容前行状态。初始空行方案1，处理完所有行后对末行全部状态求和，包含所有行都空的方案。',
        r'''int rows, cols; while (cin >> rows >> cols) { vector<int> fertile(rows); for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) { int x; cin >> x; if (x) fertile[r] |= 1 << c; } vector<int> masks; for (int mask = 0; mask < (1 << cols); mask++) if (!(mask & (mask << 1))) masks.push_back(mask); int states = masks.size(); const int mod = 100000000; vector<int> dp(states); dp[0] = 1; for (int r = 0; r < rows; r++) { vector<int> next(states); for (int a = 0; a < states; a++) if ((masks[a] & fertile[r]) == masks[a]) for (int b = 0; b < states; b++) if (!(masks[a] & masks[b])) { next[a] += dp[b]; if (next[a] >= mod) next[a] -= mod; } dp.swap(next); } int answer = 0; for (int x : dp) { answer += x; if (answer >= mod) answer -= mod; } cout << answer << '\n'; }''',
        '只有四方向限制，斜邻可以同时放。模数是100000000，不是十亿加七。', complexity=r'合法行状态数 $S\le377$，时间 $O(MS^2+2^N)$，空间 $O(S+M)$。')
    if 'nowcoder-global::15034' not in existing:
        reviewed_clone(15034, 25088, '完整核对平原01输入、上下左右不相邻、空方案与模一亿，均与Corn Fields相同；参考程序同时支持多组到EOF。')
    put(16122, 1900, ['Floyd', '状态压缩', '最短路'], '只需游览给定的R个地点，起终点自选，求总路费最少的顺序。',
        '先用Floyd求任意两点最短路，旅途中可以经过不在必游清单的地点。再对R≤15个必游点做子集DP：dp[mask][last]为已按某顺序游览mask并停在last的最少费用，转移追加一个未游点，加两者最短路费用。任一点都可以作为第一站，单点初值0，答案为全体集合的任意末站最小值，不需回到起点。',
        r'''int n,m,r; cin >> n >> m >> r; vector<int> target(r); for (int &x : target) { cin >> x; x--; } const long long inf = 1LL << 60; vector<vector<long long>> distance(n,vector<long long>(n,inf)); for (int i = 0; i < n; i++) distance[i][i] = 0; while (m--) { int a,b; long long w; cin >> a >> b >> w; --a; --b; distance[a][b] = distance[b][a] = min(distance[a][b],w); } for (int k = 0; k < n; k++) for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if (distance[i][k] != inf && distance[k][j] != inf) distance[i][j] = min(distance[i][j],distance[i][k] + distance[k][j]); vector<vector<long long>> dp(1 << r,vector<long long>(r,inf)); for (int i = 0; i < r; i++) dp[1 << i][i] = 0; for (int mask = 1; mask < (1 << r); mask++) for (int last = 0; last < r; last++) if (dp[mask][last] != inf) for (int next = 0; next < r; next++) if (!(mask >> next & 1) && distance[target[last]][target[next]] != inf) dp[mask | (1 << next)][next] = min(dp[mask | (1 << next)][next],dp[mask][last] + distance[target[last]][target[next]]); long long answer = *min_element(dp.back().begin(),dp.back().end()); cout << (answer == inf ? -1 : answer);''',
        '学校到第一站、最后一站回学校不用计费，因此初始所有单点为0，终态无需闭环。不能只在原图必游点之间的直接边上做TSP。', complexity=r'时间 $O(n^3+R^2 2^R)$，空间 $O(n^2+R2^R)$。')
    put(16544, 2200, ['状态压缩', '图上计数'], '统计无向简单环，按环长模k分类，长度必须大于2，答案模998244353。',
        '每个环固定最小编号点s作为起点，只访问编号>s的其他点，消除选起点的重复。dp[mask][last]记录从s出发、依次访问mask中的其余点并停在last的简单路径数。若last与s相连且mask至少两点，这条路径可以闭合，按(popcount(mask)+1)%k计入。继续沿未访问邻点扩展。每个无向环仍被顺、逆两个方向各算一次，最后乘2的模逆元。\n\n每次固定s单独开表，最多存(n−1)*2^(n−1)个32位数，而非对全部s同时开大表。邻接位集与最低位遍历只枚举存在的下一条边。',
        r'''int n,m,k; cin >> n >> m >> k; vector<unsigned int> adjacency(n); while (m--) { int a,b; cin >> a >> b; --a; --b; adjacency[a] |= 1U << b; adjacency[b] |= 1U << a; } const int mod = 998244353; vector<int> answer(k); for (int start = 0; start + 2 < n; start++) { int remaining = n - start - 1, masks = 1 << remaining; vector<int> dp((size_t)masks * remaining); for (int j = 0; j < remaining; j++) if (adjacency[start] >> (start + 1 + j) & 1U) dp[(size_t)(1 << j) * remaining + j] = 1;
        for (int mask = 1; mask < masks; mask++) { int length = __builtin_popcount((unsigned)mask) + 1; unsigned int ends = mask; while (ends) { int last = __builtin_ctz(ends); ends &= ends - 1; int ways = dp[(size_t)mask * remaining + last]; if (!ways) continue; int u = start + 1 + last; if (length >= 3 && (adjacency[u] >> start & 1U)) { int &target = answer[length % k]; target += ways; if (target >= mod) target -= mod; } unsigned int next = (adjacency[u] >> (start + 1)) & ~((unsigned)mask); while (next) { int v = __builtin_ctz(next); next &= next - 1; int &target = dp[(size_t)(mask | (1 << v)) * remaining + v]; target += ways; if (target >= mod) target -= mod; } } } } for (int x : answer) cout << 1LL * x * 499122177 % mod << '\n';''',
        '不把一条边来回走形成的长度2回路计入。固定最小顶点只去掉起点重复，仍需除以两个方向。', complexity=r'时间 $O(n^2 2^n)$，峰值空间 $O(n2^{n-1})$，$n\le20$。')
    put(17890, 2100, ['状态压缩', '矩阵快速幂'], 'm行n列黑白填色，左右不能同白，相邻两列不能同时全黑，n至十的十八次方。',
        '列mask的1表示白格。相邻两列a、b要求a&b=0，防止同一行左右均白；同时(a|b)≠0，防止两列全黑。每列内部上下没有限制。最多2^m≤32种状态，把合法相邻关系组成转移矩阵，第一列每种状态都有1种方案。求转移矩阵的n−1次幂，所有元素之和即最终总方案数；n=1时单位矩阵元素和为2^m。',
        r'''int m; unsigned long long n; cin >> m >> n; int states = 1 << m; const long long mod = 1000000007; using Matrix = vector<vector<long long>>; Matrix base(states,vector<long long>(states)), result = base; for (int a = 0; a < states; a++) { result[a][a] = 1; for (int b = 0; b < states; b++) base[a][b] = !(a & b) && (a | b); } auto multiply = [&](const Matrix &a, const Matrix &b) { Matrix c(states,vector<long long>(states)); for (int i = 0; i < states; i++) for (int k = 0; k < states; k++) if (a[i][k]) for (int j = 0; j < states; j++) c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % mod; return c; }; for (n--; n; n >>= 1) { if (n & 1) result = multiply(result,base); base = multiply(base,base); } long long answer = 0; for (auto &row : result) for (long long x : row) answer = (answer + x) % mod; cout << answer;''',
        '约束针对左右及相邻两列，并不限制同一列上下白格。指数为n−1，n=1不能多做一次转移。', complexity=r'状态数 $S=2^m\le32$，时间 $O(S^3\log n)$，空间 $O(S^2)$。')
    put(19885, 1900, ['计数动态规划', '组合数'], '棋盘上任意放若干中国象棋炮，使任何两炮不能隔恰好一炮互攻。',
        '同一行或列若至少三炮，其中按位置相邻的第一、第三炮恰有一个炮架，必互攻；反之每行每列至多两炮就安全。逐行放置，每行只放0、1、2炮。dp[one][two]记录已有one列放一炮、two列放两炮的方案，剩余empty列无炮。\n\n放一炮可选空列（empty种）或一炮列（one种）；放两炮有两空列、空列加一炮列、两一炮列三类，组合系数分别C(empty,2)、empty*one、C(one,2)。两炮列不能再放。按类型更新列计数并乘选择数，最后对全部列状态求和，含全空棋盘。',
        r'''int n,m; cin >> n >> m; const long long mod = 9999973; vector<vector<long long>> dp(m + 1,vector<long long>(m + 1)); dp[0][0] = 1; for (int r = 0; r < n; r++) { vector<vector<long long>> next(m + 1,vector<long long>(m + 1)); for (int one = 0; one <= m; one++) for (int two = 0; one + two <= m; two++) if (dp[one][two]) { int empty = m - one - two; long long ways = dp[one][two]; auto add = [&](int a, int b, long long choices) { next[a][b] = (next[a][b] + ways * choices) % mod; }; add(one,two,1); if (empty) add(one + 1,two,empty); if (one) add(one - 1,two + 1,one); if (empty >= 2) add(one + 2,two,1LL * empty * (empty - 1) / 2); if (empty && one) add(one,two + 1,1LL * empty * one); if (one >= 2) add(one - 2,two + 2,1LL * one * (one - 1) / 2); } dp.swap(next); } long long answer = 0; for (auto &row : dp) for (long long x : row) answer = (answer + x) % mod; cout << answer;''',
        '两炮同一行但中间没有炮架时不互攻，所以不能误用普通车的每行每列最多一个。模数为9999973。', complexity=r'时间 $O(NM^2)$，空间 $O(M^2)$。')
    put(210981, 1700, ['状态压缩', '排列计数'], '安排全部奶牛，任意相邻编号差严格大于K，统计完整队列方案。',
        'dp[mask][last]记录已放mask中的奶牛、最后一头为last的方案数。任一单头都可作起点，初值1。追加未用奶牛next时，只需检查它与last的编号差>K，满足就累加到新状态。最终对全体集合的所有末尾求和。编号不同但只按身份位标记，不按数值大小改变原索引。',
        r'''int n,k; cin >> n >> k; vector<int> a(n); for (int &x : a) cin >> x; vector<vector<long long>> dp(1 << n,vector<long long>(n)); for (int i = 0; i < n; i++) dp[1 << i][i] = 1; for (int mask = 1; mask < (1 << n); mask++) for (int last = 0; last < n; last++) if (dp[mask][last]) for (int next = 0; next < n; next++) if (!(mask >> next & 1) && abs(a[last] - a[next]) > k) dp[mask | (1 << next)][next] += dp[mask][last]; cout << accumulate(dp.back().begin(),dp.back().end(),0LL);''',
        '差恰等于K不合法。反向排列是不同队伍，答案不除二。题目保证在64位范围内。', complexity=r'时间 $O(n^2 2^n)$，空间 $O(n2^n)$。')
    put(24158, 2000, ['状态压缩', '二分'], '每部电影至多选一个场次，可中途进入退出，连续覆盖时间0到L，最少看几部。',
        'dp[mask]表示使用这些不同电影后，能从0连续覆盖到的最晚时刻，初始dp[0]=0，其余不可达。加入未选电影i时，在它的场次中二分找不晚于当前结束时刻的最晚开场；它结束也最晚。若该场仍在放映，就能接上，结束时刻扩展到开场+片长。\n\n同一电影集合只保留最远结束是充分的：既然已经覆盖到更远处，任何能从较早结束继续并向外延伸的下一场，要么也能从更远处接上，要么早已落在已覆盖区间内，后者无助于继续向外覆盖。枚举所有达到L的mask，取置一位数最小。',
        r'''int n, target; cin >> n >> target; vector<int> duration(n); vector<vector<int>> show(n); for (int i = 0; i < n; i++) { int count; cin >> duration[i] >> count; show[i].resize(count); for (int &x : show[i]) cin >> x; } vector<int> dp(1 << n,-1); dp[0] = 0; int answer = n + 1; for (int mask = 0; mask < (1 << n); mask++) if (dp[mask] != -1) { int used = __builtin_popcount((unsigned)mask); if (dp[mask] >= target) { answer = min(answer,used); continue; } if (used >= answer) continue; for (int i = 0; i < n; i++) if (!(mask >> i & 1)) { auto it = upper_bound(show[i].begin(),show[i].end(),dp[mask]); if (it == show[i].begin()) continue; int end = *prev(it) + duration[i]; if (end > dp[mask]) dp[mask | (1 << i)] = max(dp[mask | (1 << i)],end); } } cout << (answer == n + 1 ? -1 : answer);''',
        '必须从0开始无空档观看。可进入已经放映的场次，不要求开场恰好等于上一部结束时间；同一电影不能换场次重复使用。', complexity=r'每电影最多 $C$ 场，时间 $O(n2^n\log C)$，空间 $O(2^n+\sum C_i)$。')
    put(24416, 1900, ['状态压缩', '双指针', '贪心'], '依次购买全部物品，每次用一枚硬币付一段连续购买且不找零，最大化剩下硬币面值。',
        '对固定的一枚硬币、固定的已买前缀，尽量多付连续物品不会更差：后续硬币从更靠后的前缀开始，其能覆盖到的最终位置也不会更靠前。用正价格前缀和和双指针，预处理jump[coin][prefix]表示这枚硬币能把已买前缀从prefix推进到哪里。\n\ndp[mask]记录已使用硬币集合mask能买完的最长前缀，枚举下一枚硬币用jump推进。同一集合只需最远前缀，因为正价格使每枚后续硬币的推进函数单调。若已覆盖N件，剩余面值为硬币总和减mask面值和，更新最大值。',
        r'''int k,n; cin >> k >> n; vector<long long> coin(k), prefix(n + 1); long long total = 0; for (auto &x : coin) { cin >> x; total += x; } for (int i = 1; i <= n; i++) { int x; cin >> x; prefix[i] = prefix[i - 1] + x; } vector<vector<int>> jump(k,vector<int>(n + 1)); for (int i = 0; i < k; i++) { int end = 0; for (int begin = 0; begin <= n; begin++) { end = max(end,begin); while (end < n && prefix[end + 1] - prefix[begin] <= coin[i]) end++; jump[i][begin] = end; } } int masks = 1 << k; vector<int> dp(masks,-1); vector<long long> spent(masks); dp[0] = 0; long long answer = -1; for (int mask = 0; mask < masks; mask++) { if (mask) { int bit = __builtin_ctz((unsigned)mask); spent[mask] = spent[mask & (mask - 1)] + coin[bit]; } if (dp[mask] == -1) continue; if (dp[mask] == n) { answer = max(answer,total - spent[mask]); continue; } for (int i = 0; i < k; i++) if (!(mask >> i & 1)) dp[mask | (1 << i)] = max(dp[mask | (1 << i)],jump[i][dp[mask]]); } cout << answer;''',
        '剩余的是未使用硬币，已用硬币多付的部分不能找回。物品顺序固定，不可跨过买不起的当前物品。', complexity=r'时间 $O(KN+K2^K)$，空间 $O(KN+2^K)$。')


if __name__ == '__main__':
    run()
